CH = 24

UNITS = [{'id': 'PEDS-U194', 'ch': 24, 'n': 1, 'title': 'Hereditary Hyperbilirubinemias — Overview', 'sec': 'Hereditary Hyperbilirubinemias · p104', 'qs': ['PEDS-C24-001', 'PEDS-C24-002', 'PEDS-C24-003', 'PEDS-C24-004', 'PEDS-C24-005', 'PEDS-C24-006', 'PEDS-C24-007', 'PEDS-C24-008'], 'guide': 'Hereditary hyperbilirubinemias (AKA syndromic jaundice) — AR inheritance. ↑ Unconjugated BR: ↓ UDP-GT defect (Crigler Najjar, Gilbert). ↑ Conjugated BR: defect in secretion/excretion of conjugated BR from liver into bile (Dubin Johnson, Rotor).'}, {'id': 'PEDS-U195', 'ch': 24, 'n': 2, 'title': 'Crigler-Najjar Syndrome — Type I vs Type II', 'sec': 'Crigler Najjar Syndrome · p104', 'qs': ['PEDS-C24-009', 'PEDS-C24-010', 'PEDS-C24-011', 'PEDS-C24-012', 'PEDS-C24-013', 'PEDS-C24-014', 'PEDS-C24-015', 'PEDS-C24-016', 'PEDS-C24-017', 'PEDS-C24-018', 'PEDS-C24-019', 'PEDS-C24-020', 'PEDS-C24-021', 'PEDS-C24-022'], 'guide': 'Suspect type I if high bilirubin without hemolysis beyond 1st week after birth. Type I — UDP-GT absent; most severe (can be fatal); kernicterus risk high; serum BR > 20 mg/dl; supportive (phototherapy, exchange transfusion) + curative liver transplant; no response to phenobarbitone. Type II — partial deficiency; less severe; low kernicterus risk; BR < 20 mg/dl; only supportive; phenobarbitone (enzyme inducer) → ↓ jaundice.'}, {'id': 'PEDS-U196', 'ch': 24, 'n': 3, 'title': 'Gilbert Syndrome', 'sec': 'Gilbert Syndrome · p104', 'qs': ['PEDS-C24-023', 'PEDS-C24-024', 'PEDS-C24-025', 'PEDS-C24-026', 'PEDS-C24-027', 'PEDS-C24-028', 'PEDS-C24-029', 'PEDS-C24-030'], 'guide': 'Gilbert syndrome: m/c cause of hereditary hyperbilirubinemia; mild UDP-GT deficiency → m/c benign type. Onset: adolescence/puberty; mild unconjugated BR (1–6 mg/dl). Symptoms: intermittent fluctuant jaundice; any stressor (illness/fasting) precipitates. Treatment: reassurance — no intervention needed.'}, {'id': 'PEDS-U197', 'ch': 24, 'n': 4, 'title': 'Dubin-Johnson & Rotor Syndrome', 'sec': 'Dubin-Johnson and Rotor Syndrome · p105', 'qs': ['PEDS-C24-031', 'PEDS-C24-032', 'PEDS-C24-033', 'PEDS-C24-034', 'PEDS-C24-035', 'PEDS-C24-036', 'PEDS-C24-037', 'PEDS-C24-038'], 'guide': 'Transporter proteins carry conjugated bilirubin from hepatocyte to bile duct: MRP-2 (multidrug resistant protein) coded by ATP binding cassette subfamily C (ABCC) — defective in Dubin Johnson; OATP (organic anion transport protein) — defective in Rotor. Onset: adult/late adolescence; mild asymptomatic jaundice; treatment — reassurance.'}, {'id': 'PEDS-U198', 'ch': 24, 'n': 5, 'title': 'Neonatal Cholestasis — Definition & Clinical Features', 'sec': 'Neonatal Cholestasis · p105', 'qs': ['PEDS-C24-039', 'PEDS-C24-040', 'PEDS-C24-041', 'PEDS-C24-042', 'PEDS-C24-043', 'PEDS-C24-044', 'PEDS-C24-045', 'PEDS-C24-046'], 'guide': 'Neonatal cholestasis: impairment of bile flow in hepatobiliary system → ↑ conjugated BR. Biochemical: TSB < 5 mg/dl → conjugated BR ≥ 1 mg/dl; TSB > 5 mg/dl → conjugated ≥ 20% of TSB. Clinically: persistent jaundice > 3 weeks (excluding other dx), pale/clay (especially core) stools, dark yellow urine.'}, {'id': 'PEDS-U199', 'ch': 24, 'n': 6, 'title': 'Neonatal Cholestasis — Intrahepatic Causes (Hepatitis, Metabolic, Lysosomal)', 'sec': 'Etiology — Intrahepatic · p105', 'qs': ['PEDS-C24-047', 'PEDS-C24-048', 'PEDS-C24-049', 'PEDS-C24-050', 'PEDS-C24-051', 'PEDS-C24-052', 'PEDS-C24-053', 'PEDS-C24-054', 'PEDS-C24-055', 'PEDS-C24-056', 'PEDS-C24-057', 'PEDS-C24-058', 'PEDS-C24-059', 'PEDS-C24-060'], 'guide': 'Intrahepatic: 1. Idiopathic neonatal hepatitis (2nd m/c cause) 2. Infections — TORCH, sepsis 3. Metabolic — galactose-1-phosphate uridyl transferase deficiency (oil drop cataract, jaundice); tyrosinemia type I (fumaryl acetoacetate hydrolase deficiency; boiled cabbage odour of urine; hepatorenal syndrome — proximal tubular damage → Fanconi like); lysosomal storage disorders — Gaucher (glucocerebrosidase; hepatosplenomegaly, lytic bone lesions → Erlen meyer flask, pancytopenia; crumpled tissue paper HPE) & Niemann-Pick (sphingomyelinase; HSM + cherry red spots; foamy cells).'}, {'id': 'PEDS-U200', 'ch': 24, 'n': 7, 'title': 'Alagille & Zellweger Syndromes; Extrahepatic Causes', 'sec': 'Syndromes · p106', 'qs': ['PEDS-C24-061', 'PEDS-C24-062', 'PEDS-C24-063', 'PEDS-C24-064', 'PEDS-C24-065', 'PEDS-C24-066', 'PEDS-C24-067', 'PEDS-C24-068', 'PEDS-C24-069', 'PEDS-C24-070', 'PEDS-C24-071', 'PEDS-C24-072'], 'guide': 'Alagille: JAGGED 1 & NOTCH 2 gene defects; ↓ intrahepatic bile ducts + pulmonary artery stenosis = arteriohepatic dysplasia; triangular facies; vertebral defects (hemivertebra & butterfly vertebra); posterior embryotoxon (white-gray ridge at cornea near limbus on slit lamp). Zellweger: peroxisomal (PEX gene → peroxins); VLCFA accumulation; misdiagnosed as Down (similar facies + profound hypotonia). Extrahepatic: EHBA (d/t severe fibrosis) — m/c cause of neonatal cholestasis; choledochal cyst — cystic dilatation of bile duct.'}, {'id': 'PEDS-U201', 'ch': 24, 'n': 8, 'title': 'Neonatal Cholestasis — Evaluation, Biopsy & Management (Medical + Kasai)', 'sec': 'Evaluation · p106', 'qs': ['PEDS-C24-073', 'PEDS-C24-074', 'PEDS-C24-075', 'PEDS-C24-076', 'PEDS-C24-077', 'PEDS-C24-078', 'PEDS-C24-079', 'PEDS-C24-080', 'PEDS-C24-081', 'PEDS-C24-082', 'PEDS-C24-083', 'PEDS-C24-084', 'PEDS-C24-085', 'PEDS-C24-086', 'PEDS-C24-087', 'PEDS-C24-088', 'PEDS-C24-089'], 'guide': 'Evaluation: history & exam; serum bilirubin (total & conjugated); imaging primarily useful in EHBA — USG (microgallbladder/ghost; hyperechogenic atretic duct; triangular cord sign), HIDA (↓ tracer excretion; high negative predictive value). Biopsy — best investigation; differentiates intrahepatic (damaged architecture, giant cells +++, portal inflammation) vs EHBA (normal architecture, giant cells +, portal fibrosis, neoductular proliferation +). Medical: MCT oil, vitamins A/D/E/K, Cu/Mg/Zn/PO4, twice-RDA multivitamins, UDCA & cholestyramine. Surgical: Kasai (hepatoportoenterostomy) — good if < 60 days; definitive — transplant. Choledochal cyst — excision + hepaticojejunostomy.'}, {'id': 'PEDS-U202', 'ch': 24, 'n': 9, 'title': 'Wilson Disease', 'sec': 'Metabolic Liver Disease — Wilson Disease · p108', 'qs': ['PEDS-C24-090', 'PEDS-C24-091', 'PEDS-C24-092', 'PEDS-C24-093', 'PEDS-C24-094', 'PEDS-C24-095', 'PEDS-C24-096', 'PEDS-C24-097', 'PEDS-C24-098', 'PEDS-C24-099', 'PEDS-C24-100', 'PEDS-C24-101', 'PEDS-C24-102', 'PEDS-C24-103', 'PEDS-C24-104', 'PEDS-C24-105', 'PEDS-C24-106', 'PEDS-C24-107', 'PEDS-C24-108', 'PEDS-C24-109'], 'guide': 'Wilson disease: AR; ATP7B gene (chromosome 13q) → P-type ATPase defect → ↑ free copper (toxic) + ↓ ceruloplasmin. Onset > 3 yrs. Liver (children): chronic liver disease → cirrhosis → ESLD. CNS (adults): tremor, seizures, extrapyramidal, psychosis/depression (basal ganglia). Eye: Cu in descemet membrane → KF ring; sunflower cataract. Coombs –ve hemolysis; arthralgia. Screening: urine Cu ↑, ceruloplasmin ↓. Gold standard: liver biopsy — Cu > 250 µg/g dry weight; macrovesicular steatosis. Rx: copper restriction; chelators (D-penicillamine, trientene); zinc (long-term maintenance); liver transplant (definitive).'}, {'id': 'PEDS-U203', 'ch': 24, 'n': 10, 'title': 'Liver Glycogen Storage Disorders', 'sec': 'Liver Glycogen Storage Disorders (GSD) · p109', 'qs': ['PEDS-C24-110', 'PEDS-C24-111', 'PEDS-C24-112', 'PEDS-C24-113', 'PEDS-C24-114', 'PEDS-C24-115', 'PEDS-C24-116', 'PEDS-C24-117', 'PEDS-C24-118', 'PEDS-C24-119', 'PEDS-C24-120', 'PEDS-C24-121', 'PEDS-C24-122', 'PEDS-C24-123', 'PEDS-C24-124', 'PEDS-C24-125', 'PEDS-C24-126', 'PEDS-C24-127', 'PEDS-C24-128', 'PEDS-C24-129'], 'guide': 'GSD: fasting glycogen not broken down → defect. Presentation: recurrent fasting hypoglycemia; hepatomegaly (glycogen accumulation); muscle involvement in certain subtypes (exertional fatigue, ↓ ATP). Types: 0 — glycogen synthase (no glycogen deposit); I von Gierke — G6Pase (m/c); II (Cori, as per book) — debranching (muscle involvement); III (Anderson, as per book) — branching (2nd m/c; early cirrhosis, worst outcome); VI Hers — liver phosphorylase; IX — phosphorylase kinase. Von Gierke: doll facies, renomegaly, ↑ uric acid (PPP→purines), hyperlipidemia (pyruvate→acetyl CoA→FA), lactic acidosis; lactate & uric acid ↑↑↑ vs type III (–). Rx: frequent feeds 2–3 hrly; uncooked corn starch; night feeds (NG young, waxy maize starch older).'}]

